import re
import os
from pathlib import Path
import yaml
from auto_config.generator.utils.get_bts_config import Config

PROFILES_PATH = Path(os.path.abspath(__file__)).parents[2] / "config" / "profiles"


def get_bbmod_smod_depend_on_profile(chosen_tl_label, bbmod_smod_yaml, rmods_yaml):
    enb_yaml_path_depend_on_profile = PROFILES_PATH / chosen_tl_label / "enb.yaml"
    ue_yaml_path_depend_on_profile = PROFILES_PATH / chosen_tl_label / "ue.yaml"

    enb_id = ""
    enb_yaml_to_parse = _open_yaml_file(enb_yaml_path_depend_on_profile)
    enb_yaml = Config.get_config(enb_yaml_to_parse, enb_id, rmods_yaml, bbmod_smod_yaml)
    ue_yaml = _open_yaml_file(ue_yaml_path_depend_on_profile)

    bbmods_prod_code_dict = {}
    smods_prod_code_dict = {}
    enbs_dict = {}

    mplane_only_cells = _get_mplane_only_cels(ue_yaml)

    for enb in enb_yaml.keys():
        bbmods_dict = enb_yaml[enb].get('bbmods')
        smods_dict = enb_yaml[enb].get('smods')
        rmods_dict = enb_yaml[enb].get('radios')
        cells_dict = enb_yaml[enb].get('cells')

        bbmods_dict = _parse_bbmods(bbmods_dict, bbmods_prod_code_dict, bbmod_smod_yaml)
        smods_dict = _parse_smods(smods_dict, smods_prod_code_dict, bbmod_smod_yaml)
        cells_dict = _parse_cells(cells_dict, mplane_only_cells)

        enbs_dict[enb] = {
            "bbmods": bbmods_dict,
            "smods": smods_dict,
            "rmods": rmods_dict,
            "cells": cells_dict
        }

    return enbs_dict


def _get_connections(cells):
    connections = {}
    channels = cells['channels']
    for channel in channels:
        direction = channel['direction']
        radio = channel['radio']
        port = channel['port']

        if radio not in connections:
            connections[radio] = {}

        if port not in connections[radio]:
            connections[radio][port] = ''

        if direction == 'TX':
            connections[radio][port] += 'TX'

        elif direction == 'RX':
            connections[radio][port] += 'RX'
    return connections


def _get_mplane_only_cels(ue_yaml_file):
    mplane_only_cells = []
    for cus_key in filter(lambda x: x.startswith('cus'), ue_yaml_file.keys()):
        cus_ent = ue_yaml_file[cus_key]
        if 'mplane_only' in cus_ent:
            mplane_cell = cus_ent['mplane_only']
            if isinstance(mplane_cell, list):
                mplane_only_cells.extend(mplane_cell)
            else:
                mplane_cell.append(mplane_cell)
    return mplane_only_cells


def _open_yaml_file(path):
    with open(path) as f:
        return yaml.load(f, Loader=yaml.BaseLoader)


def _parse_bbmods(bbmods_dict, bbmods_prod_code_dict, bbmod_smod_yaml):
    if not bbmods_dict:
        return {}

    for bbmod in bbmods_dict:
        bbmods_prod_code_dict[bbmod] = bbmods_dict[bbmod].get("prod_code_planned", '473096A')

    for bbmod_nr in bbmods_prod_code_dict:
        for bbmod_name, bbmod_params in bbmod_smod_yaml['BBMODS'].items():
            prod_code_planned = bbmod_params.get('prod_code_planned', '')
            if isinstance(prod_code_planned, list):
                prod_code_planned = prod_code_planned[0]
            if re.search(prod_code_planned, bbmods_prod_code_dict[bbmod_nr]):
                bbmods_dict[bbmod_nr] = bbmod_name

    return bbmods_dict


def _parse_smods(smods_dict, smods_prod_code_dict, bbmod_smod_yaml):
    if smods_dict:
        for smod in smods_dict:
            if smods_dict[smod].get("type"):
                smods_dict[smod] = smods_dict[smod].get("type")
                return smods_dict
            smods_prod_code_dict[smod] = smods_dict[smod].get("prod_code_planned")
    else:
        smods_dict = {}
        smods_prod_code_dict["1"] = '473095A'

    for smod_nr in smods_prod_code_dict.keys():
        for smod_name, smod_params in bbmod_smod_yaml['SMODS'].items():
            if re.search(smod_params.get('prod_code_planned'), smods_prod_code_dict[smod_nr]):
                smods_dict[smod_nr] = smod_name

    return smods_dict


def _parse_cells(cells_dict, mplane_only_cells):
    for id, cells in cells_dict.items():
        connections = _get_connections(cells)
        for radio in connections:
            for port in range(1, 9):
                if str(port) not in connections[radio]:
                    connections[radio][str(port)] = ''

        cells_dict[id]['mplane_only'] = id in mplane_only_cells
        del cells_dict[id]['channels']
        cells_dict[id]["connections"] = {"radio": connections}

    return cells_dict
